00044 BaseScreen* LogViewerScreen::handle_input(Controller& controller, const worker_map_t& workers) {
00045   auto button1 = workers.worker<ZenButton>(k_worker_button_1);
00046   auto button2 = workers.worker<ZenButton>(k_worker_button_2);
00047   auto button3 = workers.worker<ZenButton>(k_worker_button_3);
00048 
00049 
00050   if (strlen(_detail_log_file_name) > 0) {
00051     // detail view
00052     if (button1->is_fresh() && button1->get_data().shortPress) {
00053       // Back
00054       force_next_render();
00055       leave_detail();
00056       return nullptr;
00057     }
00058     if (button2->is_fresh() && button2->get_data().shortPress) {
00059       force_next_render();
00060       if (!_detail_log_upload_id) {
00061         // Upload
00062         upload_detail(controller.get_settings());
00063       }
00064     }
00065     if (button3->is_fresh() && button3->get_data().shortPress) {
00066       return &MenuWindow_i;
00067     }
00068   } else {
00069     // not detail view
00070     if (button1->is_fresh() && button1->get_data().shortPress) {
00071       force_next_render();
00072       // TODO: selector down
00073       return nullptr;
00074     }
00075     if (button2->is_fresh() && button2->get_data().shortPress) {
00076       if (_current_view == e_log_main_view) {
00077         force_next_render();
00078         _current_view = e_log_drive_view;
00079       } else {
00080         force_next_render();
00081         // TODO: enter detail down
00082         enter_detail("/drives/2024-11-30_1227.log");
00083       }
00084     }
00085     if (button3->is_fresh() && button3->get_data().shortPress) {
00086       return &MenuWindow_i;
00087     }
00088   }
00089 
00090   return nullptr;
00091 }
