00093 void LogViewerScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
00094   if (!force) {
00095     return;
00096   }
00097 
00098   clear_screen_content();
00099 
00100   if (strlen(_detail_log_file_name) > 0) {
00101     return render_log_detail(workers, handlers, force);
00102   }
00103 
00104   switch (_current_view) {
00105     case e_log_main_view:
00106       return render_main(workers, handlers, force);
00107     case e_log_journal_view:
00108       return render_journal_log_list(workers, handlers, force);
00109     case e_log_drive_view:
00110       return render_drive_log_list(workers, handlers, force);
00111     case e_log_survey_view:
00112       return render_survey_log_list(workers, handlers, force);
00113     default:
00114       return;
00115   }
00116 }
