00168 void LogViewerScreen::enter_detail(const char* log_name) {
00169   char dir[100];
00170   strcpy(_detail_log_file_path, log_name);
00171   if (sscanf(_detail_log_file_path, "/%[^/]/%s", dir, _detail_log_file_name) == 0) {
00172     strcpy(_detail_log_file_name, "Unknown log name");
00173     return;
00174   }
00175   if (sscanf(_detail_log_file_name, "%4hu-%2hhu-%2hhu_%2hhu%2hhu.log", &_detail_log_timestamp.year, &_detail_log_timestamp.month, &_detail_log_timestamp.day, &_detail_log_timestamp.hour, &_detail_log_timestamp.minute) != 5) {
00176     _detail_log_timestamp.clear();
00177   }
00178 
00179   // TODO: parse log_name
00180 }
