00199 void LogViewerScreen::upload_detail(const LocalStorage& config) {
00200   File log_file = SDInterface::i().get_file(_detail_log_file_path);
00201 
00202   if (!log_file) {
00203     M5_LOGD("Failed to open log file!");
00204     return;
00205   }
00206 
00207   char url[100];
00208   sprintf(url, "%s?api_key=%s&", API_LOGFILE_ENDPOINT, config.get_api_key());
00209 
00210   ChunkedHTTPClient http;
00211   WiFiClient client;
00212 
00213   // Specify destination for HTTP request
00214   if (!http.begin(client, url)) {
00215     M5_LOGD("Unable to begin URL connection");
00216     http.end(); // Free resources
00217     return;
00218   }
00219 
00220   // Define boundary and headers
00221   char boundary[32];
00222   sprintf(boundary, "----WebKitFormBoundaryZen%d", config.get_device_id());
00223   char content_type_header[150];
00224   sprintf(content_type_header, "multipart/form-data; boundary=%s", boundary);
00225 
00226   http.setUserAgent(HEADER_API_USER_AGENT);
00227   http.addHeader("Host", TTSERVE_HOST);
00228   http.addHeader("Content-Type", content_type_header);
00229   http.addHeader("Transfer-Encoding", "chunked");
00230 
00231   char chunk_header[16];
00232   char chunk_buffer[512];
00233   size_t chunk_length;
00234 
00235 
00236   if (http.sendPOSTHeaders()) {
00237     // 1. Send the opening boundary and metadata for the file part as a chunk
00238     sprintf(chunk_buffer,
00239             "--%s\r\n"
00240             "Content-Disposition: form-data; name=\"bgeigie_import[description]\"\r\n"
00241             "Uploaded from Zen\r\n\r\n"
00242             "--%s\r\n"
00243             "Content-Disposition: form-data; name=\"bgeigie_import[source]\"; filename=\"%s\"\r\n"
00244             "Content-Type: text/plain\r\n\r\n",
00245             boundary, boundary, "2024-11-30_1227.log");
00246 
00247     // Calculate header length
00248     chunk_length = strlen(chunk_buffer);
00249     sprintf(chunk_header, "%X\r\n", chunk_length); // Chunk size in hexadecimal
00250     client.print(chunk_header);              // Send chunk size
00251     client.print(chunk_buffer);   // Send chunk data
00252     client.print("\r\n");                                   // End of chunk
00253     M5_LOGD("Header chunk sent (%X):\n%s", chunk_length, chunk_buffer);
00254 
00255     // 2. Stream the file content line by line as chunks
00256     while (log_file.available()) {
00257       chunk_length = log_file.readBytesUntil('\n', chunk_buffer, 511); // Read a line from the file
00258       chunk_buffer[chunk_length] = '\n'; // Add the newline character back
00259       chunk_buffer[chunk_length + 1] = '\0'; // Null-terminate the buffer
00260 
00261       sprintf(chunk_header, " %X\r\n", chunk_length + 1); // Chunk size in hexadecimal (include '\n')
00262       client.print(chunk_header);              // Send chunk size
00263       client.print(chunk_buffer);               // Send chunk data
00264       client.print("\r\n");                                   // End of chunk
00265     }
00266 
00267     // 3. Send the closing boundary as a chunk
00268     sprintf(chunk_buffer, "--%s--\r\n", boundary);
00269     chunk_length = strlen(chunk_buffer);
00270     sprintf(chunk_header, "%X\r\n", chunk_length); // Chunk size in hexadecimal
00271     client.print(chunk_header);                              // Send chunk size
00272     client.print(chunk_buffer);                          // Send chunk data
00273     client.print("\r\n");                                   // End of chunk
00274     M5_LOGD("Closing boundary chunk sent (%X):\n%s", chunk_length, chunk_buffer);
00275 
00276     // 4. End the chunked transfer by sending a zero-size chunk
00277     client.print("0\r\n\r\n");
00278     M5_LOGD("End of chunked transfer");
00279 
00280     // 5. Wait for the server response
00281     int statusCode = http.handleResponse();
00282     String response = http.getString();
00283     M5_LOGD("POST complete, (code %d) response:\n%s", statusCode, response.c_str());
00284 
00285     WiFiWrapper_i.update_active();
00286   } else {
00287     M5_LOGD("Failed to initiate request");
00288   }
00289 
00290   http.end(); // Free resources
00291 
00292 
00293   log_file.close(); // Close file
00294 
00295 }
